  ('91932ba1-9756-5a56-ae1f-6f9187135ecf', '1c917f14-e30e-5b9b-9cec-96227a26e9a9', 'Why Wording Matters', 'The same message, received completely differently.', 0, 'published'),
  ('34224fa3-34ac-5bf6-9b51-9eb9d55ce94a', '1c917f14-e30e-5b9b-9cec-96227a26e9a9', 'Buying Time and Clarifying', 'Hold, repeat, clarify, verify.', 1, 'published'),
  ('8a503a5d-f90e-56c3-afde-a327455dd884', '1c917f14-e30e-5b9b-9cec-96227a26e9a9', 'Saying No Without Losing the Customer', 'Every no needs an alternative attached.', 2, 'published'),
  ('758058f0-fb44-58a0-840e-45d4b9716f10', '1c917f14-e30e-5b9b-9cec-96227a26e9a9', 'Conflict, Complaints, and Blame', 'Stay factual, never assign fault.', 3, 'published'),
  ('da82020d-fe15-5871-b069-2d37ba48b650', '1c917f14-e30e-5b9b-9cec-96227a26e9a9', 'Price, Closing, and Callbacks', 'Where imprecise words cost money.', 4, 'published'),
